+    class SlidePresentation {
+      constructor() {
+        this.slides = Array.from(document.querySelectorAll('.slide'));
+        this.currentSlide = 0;
+
+        this.progress = document.querySelector('.progress-bar');
+        this.nav = document.querySelector('.nav-dots');
+
+        this.setupIntersectionObserver();
+        this.setupNavDots();
+        this.setupKeyboardNav();
+        this.setupTouchNav();
+        this.setupProgressBar();
+        this.snapToHash();
+      }
+
+      setupIntersectionObserver() {
+        const observer = new IntersectionObserver(
+          (entries) => {
+            for (const entry of entries) {
+              if (entry.isIntersecting) {
+                entry.target.classList.add('visible');
+                const idx = this.slides.indexOf(entry.target);
+                if (idx >= 0) this.currentSlide = idx;
+                this.updateNavDots();
+                this.updateProgressBar();
+                this.updateHash();
+              }
+            }
+          },
+          { threshold: 0.55 }
+        );
+        this.slides.forEach((s) => observer.observe(s));
+      }
+
+      setupProgressBar() {
+        const onScroll = () => {
+          this.updateProgressBar();
+        };
+        window.addEventListener('scroll', onScroll, { passive: true });
+      }
+
+      setupNavDots() {
+        this.nav.innerHTML = '';
+        this.dots = this.slides.map((slide, idx) => {
+          const dot = document.createElement('button');
+          dot.className = 'nav-dot';
+          dot.type = 'button';
+          dot.setAttribute('aria-label', `Go to slide ${idx + 1}`);
+          dot.addEventListener('click', () => this.goTo(idx));
+          this.nav.appendChild(dot);
+          return dot;
+        });
+        this.updateNavDots();
+      }
+
+      updateNavDots() {
+        if (!this.dots) return;
+        this.dots.forEach((d, i) => d.classList.toggle('active', i === this.currentSlide));
+      }
+
+      updateProgressBar() {
+        if (!this.progress) return;
+        const maxScroll = document.documentElement.scrollHeight - window.innerHeight;
+        const pct = maxScroll <= 0 ? 0 : (window.scrollY / maxScroll);
+        this.progress.style.width = `${Math.max(0, Math.min(1, pct)) * 100}%`;
+      }
+
+      goTo(idx) {
+        const clamped = Math.max(0, Math.min(this.slides.length - 1, idx));
+        this.slides[clamped].scrollIntoView({ behavior: 'smooth' });
+      }
+
+      next() { this.goTo(this.currentSlide + 1); }
+      prev() { this.goTo(this.currentSlide - 1); }
+
+      setupKeyboardNav() {
+        window.addEventListener('keydown', (e) => {
+          const key = e.key;
+          if (key === 'ArrowDown' || key === 'PageDown' || key === ' ') {
+            e.preventDefault();
+            this.next();
+          }
+          if (key === 'ArrowUp' || key === 'PageUp') {
+            e.preventDefault();
+            this.prev();
+          }
+          if (key === 'Home') {
+            e.preventDefault();
+            this.goTo(0);
+          }
+          if (key === 'End') {
+            e.preventDefault();
+            this.goTo(this.slides.length - 1);
+          }
